mapper.select:

where i.combination_id = #{combinationId}
  and i.image_state = 'B'
order by i.image_id


left join fx67ll_dortmund_return_combination c on c.combination_id = i.combination_id

    (
        (i.image_state = 'T' and i.expire_time is not null and i.expire_time <= now())
        or (i.image_state = 'B' and (c.combination_id is null or c.adopted_flag <> 'Y'))
        or (i.image_state in ('D', 'Q') and (i.next_retry_time is null or i.next_retry_time <= now()))
    )
    and i.user_id = #{userId}

        and i.create_time >= #{beginCreateTime}


        and i.create_time <= #{endCreateTime}


order by i.create_time desc, i.image_id desc

mapper.delete:
delete from fx67ll_dortmund_return_image
where image_id = #{imageId}
  and image_state = 'D'
